class Solution {
    private int swaps(String s,char start){
        int mismatch=0;
        for(int i=0;i<s.length();i++){
            char expected=(i%2==0)?start:(start=='0'?'1':'0');
            if(s.charAt(i)!=expected)mismatch++;
        }
        return mismatch/2;
    }
    public int minSwaps(String s){
        int zeros=0;
        for(char value:s.toCharArray())if(value=='0')zeros++;
        int ones=s.length()-zeros;
        if(Math.abs(zeros-ones)>1)return -1;
        if(zeros==ones)return Math.min(swaps(s,'0'),swaps(s,'1'));
        return swaps(s,zeros>ones?'0':'1');
    }
}

